import test from 'node:test';
import assert from 'node:assert/strict';
import { singleLineCheck } from '../src/runtime/line-filter.mjs';

// Captures from original Engine.dll 0x1039aed0, regenerated by
// validate-native-line-filter.mjs. No assets or native code are test inputs.
const start = [10.125, -20.5, Math.fround(.001)], end = [-100.75, 29.25, Math.fround(-.003)];
const initial = () => ({ next: 'sentinel', actor: 'sentinel', location: [101.5, -202.25, 303.125],
  normal: [.25, -.5, .75], primitive: 0x12345678, time: .875, item: -999 });
const candidate = (actor, i = 0, time = .25, next = null) => ({ actor, next,
  location: [Math.fround(i + .1), -23.75, 123], normal: [0, 1, 0], primitive: 0x11000000 + i, time, item: i - 17 });
function check(hits, flags, source = null, extent = [0, 0, 0], extra = 0) {
  const events = [], result = initial(), levelInfo = {};
  const outside = singleLineCheck({ levelInfo,
    isA(actor, kind) { return actor.kind === kind || actor.kind === 'LevelInfo' && kind === 'ZoneInfo'; },
    multiLineCheck(end, start, extent, checkActors, info, extra) {
      events.push({ end, start, extent, checkActors, world: info === levelInfo, extra }); return hits;
    },
  }, result, source, end, start, flags, extent, extra);
  return { outside, result, events };
}

test('original placement flags accept a mover independently of its blocking bits', () => {
  // Native case 252.
  const mover = { kind: 'Mover', collisionBits: 0 }, input = candidate(mover);
  const { outside, result, events } = check([input], 6, null, [0, 0, 0], 252);
  assert.equal(outside, 0);
  assert.deepEqual(result, { next: null, actor: mover, location: [.10000000149011612, -23.75, 123],
    normal: [0, 1, 0], primitive: 285212672, time: .25, item: -17 });
  assert.notEqual(result.location, input.location);
  assert.deepEqual(events, [{ end, start, extent: [0, 0, 0], checkActors: 1, world: true, extra: 252 }]);
});

test('original filter preserves supplied list order even with a time-one hit first', () => {
  // Native case 275: this controlled list is deliberately in descending time
  // order. Sorting belongs to MultiLineCheck, not this selection routine.
  const actors = ['LevelInfo', 'Pawn', 'Mover', 'ZoneInfo', 'Actor'].map(kind => ({ kind, collisionBits: 28 }));
  const hits = actors.map((actor, i) => candidate(actor, i, 1 - i * .125, i < 4 ? i + 1 : null));
  const { outside, result } = check(hits, 6, null, [20, 20, 43]);
  assert.equal(outside, 0);
  assert.equal(result.actor, actors[0]);
  assert.equal(result.time, 1);
  assert.equal(result.next, 1);
});

test('original LevelInfo rule precedes ZoneInfo and a miss preserves other result fields', () => {
  // Native case 320. ZoneInfo flag alone also leaves actor queries disabled.
  const { outside, result, events } = check([candidate({ kind: 'LevelInfo' })], 8, null, [0, 0, 0], 63);
  assert.equal(outside, 1);
  assert.deepEqual(result, { ...initial(), actor: null, time: 1 });
  assert.deepEqual(events, [{ end, start, extent: [0, 0, 0], checkActors: 0, world: false, extra: 63 }]);
});

test('original restricted general-actor traces require both blocking bits when not a target', () => {
  // Native cases 1945 and 1947.
  assert.equal(check([candidate({ kind: 'Actor', collisionBits: 4 })], 48).outside, 1);
  const actor = { kind: 'Actor', collisionBits: 12 };
  const { outside, result } = check([candidate(actor)], 48);
  assert.equal(outside, 0);
  assert.equal(result.actor, actor);
  assert.equal(result.time, .25);
});

test('original source-owner traversal excludes ancestors while retaining a child at equal time', () => {
  // Native case 2231.
  const ancestor = { kind: 'Actor', collisionBits: 28 };
  const owner = { kind: 'Mover', owner: ancestor };
  const source = { kind: 'Pawn', owner };
  const child = { kind: 'Actor', owner: source, collisionBits: 28 };
  const sibling = { kind: 'Pawn', owner };
  const hits = [source, owner, ancestor, child, sibling].map((actor, i) => candidate(actor, i, .25, i < 4 ? i + 1 : null));
  const { outside, result } = check(hits, 55, source, [20, 20, 43]);
  assert.equal(outside, 0);
  assert.deepEqual(result, { next: 4, actor: child, location: [3.0999999046325684, -23.75, 123],
    normal: [0, 1, 0], primitive: 285212675, time: .25, item: -14 });
});
